package com.arena.core.facility;
import com.arena.core.training.*;import com.arena.core.entity.*;import com.arena.core.service.*;import com.arena.core.exception.*;import org.junit.jupiter.api.*;import org.springframework.security.oauth2.jwt.Jwt;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LegacyFacilityBoundaryTest {
 AcademyAuthorization auth=mock(AcademyAuthorization.class);AcademySetupService setup=mock(AcademySetupService.class);AcademySportRepository sports=mock(AcademySportRepository.class);AcademyPlayAreaRepository areas=mock(AcademyPlayAreaRepository.class);AcademyFacilityService service=new AcademyFacilityService(auth,setup,sports,areas,mock(AuditService.class));Jwt jwt=Jwt.withTokenValue("unit").header("alg","none").subject("owner").build();AcademySport sport;
 @BeforeEach void prepare(){when(auth.manage(jwt)).thenReturn(new AcademyAuthorization.Actor(AppUserEntity.builder().customerId(10L).build(),null,Set.of("OWNER")));when(setup.academy(10L)).thenReturn(CustomerEntity.builder().id(10L).build());sport=new AcademySport();sport.setId(20L);sport.setAcademyId(10L);sport.setCatalogueCode("SNOOKER");sport.setActive(true);sport.setSessions(true);when(sports.findById(20L)).thenReturn(Optional.of(sport));}
 @Test void oldCreationEndpointCannotAcceptAuthoritativeCodesForSupportedSports(){assertThrows(FacilityFailure.class,()->service.save(jwt,null,new AcademyFacilityService.Area(null,20L,"Table","E99","TABLE",null,true)));verify(areas,never()).saveAndFlush(any());}
 @Test void oldEndpointCannotEditNewManagedFacilities(){var f=new AcademyPlayArea();f.setId(30L);f.setAcademyId(10L);f.setSportId(20L);f.setFacilityType("ENGLISH");when(areas.findById(30L)).thenReturn(Optional.of(f));assertThrows(ArenaOpsException.class,()->service.save(jwt,30L,new AcademyFacilityService.Area(0L,20L,"Table","E1","TABLE",null,true)));verify(areas,never()).saveAndFlush(any());}
 @Test void legacyCodesCannotBeRenamedThroughOldEndpoint(){var f=new AcademyPlayArea();f.setId(30L);f.setAcademyId(10L);f.setSportId(20L);f.setVersion(0L);f.setCode("E1");when(areas.findById(30L)).thenReturn(Optional.of(f));assertThrows(FacilityFailure.class,()->service.save(jwt,30L,new AcademyFacilityService.Area(0L,20L,"Table","E2","TABLE",null,true)));verify(areas,never()).saveAndFlush(any());}

 @Test void genericLegacyFacilityCannotBeMovedAwayFromInactiveParentSport(){
  sport.setCatalogueCode("CRICKET");sport.setActive(false);var target=new AcademySport();target.setId(21L);target.setAcademyId(10L);target.setActive(true);target.setSessions(true);target.setCatalogueCode("FOOTBALL");when(sports.findById(21L)).thenReturn(Optional.of(target));var f=new AcademyPlayArea();f.setId(30L);f.setAcademyId(10L);f.setSportId(20L);when(areas.findById(30L)).thenReturn(Optional.of(f));assertEquals(ErrorCode.FACILITY_CAPABILITY_DISABLED,assertThrows(ArenaOpsException.class,()->service.save(jwt,30L,new AcademyFacilityService.Area(0L,21L,"Field","F1","FIELD",null,false))).getErrorCode());verify(areas,never()).saveAndFlush(any());
 }
}
